
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_scan_e0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_scan_e0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.983194556741272e-02, -6.897711575505974e-02, -6.775953927443806e-02, -6.603302775245808e-02, -6.360126591994367e-02, -6.021194055595750e-02, -5.556942582652499e-02, -4.940652738411076e-02, -4.172497142050860e-02, -3.350168626832913e-02, -2.900873424699013e-02, -4.277633907427097e-02, -4.762526624226614e-02, -3.712512209219372e-02, -2.587075576139871e-02, -1.524865670719139e-02, -6.849496781048878e-03, -2.014508132480143e-03, -3.076205692295133e-04, -1.649210654906304e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


